import { Component, OnInit } from '@angular/core';
import {LicnaKarta} from "../../models/LicnaKarta";
import {ZahteviService} from "../../services/Zahtevi.service";

@Component({
  selector: 'app-licna',
  templateUrl: './licna.component.html',
  styleUrls: ['./licna.component.css']
})
export class LicnaComponent implements OnInit {

  zahtevi: LicnaKarta[] = [];
  token: string = ''; // postavi JWT token iz Auth servisa

  constructor(private zahteviService: ZahteviService) { }

  ngOnInit(): void {
    this.ucitajZahteve();
  }

  ucitajZahteve() {
    this.zahteviService.getSviZahtevi(this.token).subscribe({
      next: (data) => this.zahtevi = data,
      error: (err) => console.error(err)
    });
  }

  podnesiZahtev() {
    // primer poziva servisa
    // this.zahteviService.podnesiZahtev(this.token, {jmbg: '...', ...}).subscribe(...)
  }

  produziLicnu() {
    this.zahteviService.produziLicnu(this.token).subscribe({
      next: () => this.ucitajZahteve(), // osveži tabelu
      error: (err) => console.error(err)
    });
  }

}
<div class="container mt-5">


  <!-- Naslov tabele -->
  <h3 class="mb-3 text-center">Lična Zahtevi</h3>

  <!-- Tabela sa zahtevima -->
  <div class="table-responsive">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th>
        <th>Ime</th>
        <th>Prezime</th>
        <th>JMBG</th>
        <th>Datum izdavanja</th>
        <th>Važi do</th>
        <th>Status</th>
        <th>Grad</th>
        <th>Država</th>
      </tr>
      </thead>
      <tbody>
      <tr *ngFor="let zahtev of zahtevi; let i = index">
        <td>{{ i + 1 }}</td>
        <td>{{ zahtev.ime }}</td>
        <td>{{ zahtev.prezime }}</td>
        <td>{{ zahtev.jmbg }}</td>
        <td>{{ zahtev.datumIzdavanja | date:'dd.MM.yyyy' }}</td>
        <td>{{ zahtev.datumVazenja | date:'dd.MM.yyyy' }}</td>
        <td>{{ zahtev.status }}</td>
        <td>{{ zahtev.grad }}</td>
        <td>{{ zahtev.drzava }}</td>
      </tr>
      </tbody>
    </table>
  </div>
  <!-- Dugmici za akcije -->
  <div class="d-flex justify-content-center mb-4">
    <button class="btn btn-primary me-3">Zahtev za vađenje lične</button>
    <button class="btn btn-secondary">Zahtev za produžavanje lične</button>
  </div>

</div>
